#!/usr/bin/env node
// One-off/rerunnable generator for shells/bar's PWA icons (issue #4).
// Not part of npm run check:all — icons are static output, committed once
// and regenerated by hand (`node scripts/generate-pwa-icons.mjs`) only when
// the badge design changes. Renders the same "A" badge already used in the
// bar shell's scaffold (see BarShellHome.tsx / project/Bar App.dc.html) via
// `sharp`, already a transitive dependency of `next` for image
// optimization — no new dependency needed just for this.
import { mkdirSync } from "fs";
import { dirname, join } from "path";
import { fileURLToPath } from "url";
import sharp from "sharp";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const outDir = join(root, "public", "icons");
mkdirSync(outDir, { recursive: true });

const ACCENT = "#ee5a24";

/**
 * `any`-purpose badge: rounded square, same shape language as the in-app
 * logo badge (border-radius ~30% of size in the prototype/scaffold).
 */
function anySvg(size) {
  const radius = size * 0.22;
  const fontSize = size * 0.56;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
  <rect width="${size}" height="${size}" rx="${radius}" fill="${ACCENT}"/>
  <text x="50%" y="50%" text-anchor="middle" dominant-baseline="central"
    font-family="Manrope, -apple-system, BlinkMacSystemFont, sans-serif"
    font-weight="800" font-size="${fontSize}" fill="#ffffff">A</text>
</svg>`;
}

/**
 * `maskable`-purpose badge: edge-to-edge fill (the OS applies its own
 * mask/crop), content kept inside the standard 80%-diameter safe zone so
 * nothing important gets clipped. https://web.dev/maskable-icon/
 */
function maskableSvg(size) {
  const fontSize = size * 0.42;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
  <rect width="${size}" height="${size}" fill="${ACCENT}"/>
  <text x="50%" y="50%" text-anchor="middle" dominant-baseline="central"
    font-family="Manrope, -apple-system, BlinkMacSystemFont, sans-serif"
    font-weight="800" font-size="${fontSize}" fill="#ffffff">A</text>
</svg>`;
}

const targets = [
  { name: "icon-any-192.png", svg: anySvg(192), size: 192 },
  { name: "icon-any-512.png", svg: anySvg(512), size: 512 },
  { name: "icon-maskable-192.png", svg: maskableSvg(192), size: 192 },
  { name: "icon-maskable-512.png", svg: maskableSvg(512), size: 512 },
  // iOS ignores alpha and manifest icons entirely — wants its own solid,
  // non-transparent apple-touch-icon. Same badge as `any`.
  { name: "apple-touch-icon.png", svg: anySvg(180), size: 180 },
];

for (const { name, svg, size } of targets) {
  const out = join(outDir, name);
  await sharp(Buffer.from(svg))
    .resize(size, size)
    .png()
    .toFile(name === "apple-touch-icon.png" ? join(root, "public", name) : out);
  console.log(`wrote ${name} (${size}x${size})`);
}
